import java.io.*;
import java.util.*;

public class C421 {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        int a = in.nextInt();
        int b = in.nextInt();
        int l = in.nextInt() - 1;
        int r = in.nextInt() - 1;

        int len = a + b;
        int ans;
        if (r - l >= 2 * len) {
            ans = Math.max(a + 1, 2 * a - b);
        } else {
            r -= len * (l / len);
            l %= len;
            ans = count(a, b, l, r);
        }
        System.out.println(ans);
    }

    static int count(int a, int b, int l, int r) {
        String s = build(a, b, l);
        Set<Character> set = new HashSet<>();
        for (int i = l; i <= r; ++i) {
            set.add(s.charAt(i));
        }
        return set.size();
    }

    static String build(int a, int b, int l) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < a; ++i) {
            sb.append((char) ('a' + i));
        }
        char c = l < a ? sb.charAt(a - 1) : sb.charAt(b < a ? b : a - 1);
        for (int i = 0; i < b; ++i) {
            sb.append(c);
        }

        boolean[] used = new boolean[30];
        for (int i = 0; i < a; ++i) {
            used[sb.charAt(sb.length() - i - 1) - 'a'] = true;
        }

        int p = 0;
        for (int i = 0; i < a; ++i) {
            while (used[p]) {
                ++p;
            }
            sb.append((char) ('a' + p));
            used[p] = true;
        }

        c = sb.charAt(Math.min(b, a - 1) + a + b);
        for (int i = 0; i < b; ++i) {
            sb.append(c);
        }
        for (int i = 0; i < a + b; ++i) {
            sb.append(sb.charAt(i));
        }
        return sb.toString();
    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (this.numChars == -1) {
                throw new InputMismatchException();
            }
            if (this.curChar >= this.numChars) {
                this.curChar = 0;
                try {
                    this.numChars = this.stream.read(this.buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (this.numChars <= 0) {
                    return -1;
                }
            }
            return this.buf[this.curChar++];
        }

        public int nextInt() {
            int c;
            for (c = this.read(); isSpaceChar(c); c = this.read()) {
            }
            byte sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = this.read();
            }
            int res = 0;
            while (c >= '0' && c <= '9') {
                res *= 10;
                res += c - '0';
                c = this.read();
                if (isSpaceChar(c)) {
                    return res * sgn;
                }
            }
            throw new InputMismatchException();
        }

        public static boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}
